package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	Role     string `json:"role"`
	Salary   int    `json:"salary,omitempty"`
	SSN      string `json:"ssn,omitempty"`
}

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler handles employee directory searches
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", 405)
		return
	}

	// Extract tenant context from request metadata
	tenantDB := r.Header.Get("X-Tenant-Schema")
	if tenantDB == "" {
		tenantDB = "public"
	}

	name := r.URL.Query().Get("name")
	dept := r.URL.Query().Get("dept")
	orderBy := r.URL.Query().Get("order")

	// Build search query with tenant isolation
	var conditions []string
	var args []interface{}
	argIdx := 1

	if name != "" {
		conditions = append(conditions, fmt.Sprintf("name ILIKE $%d", argIdx))
		args = append(args, "%"+name+"%")
		argIdx++
	}
	if dept != "" {
		conditions = append(conditions, fmt.Sprintf("department = $%d", argIdx))
		args = append(args, dept)
		argIdx++
	}

	query := fmt.Sprintf("SELECT id, name, email, role FROM %s.employees", tenantDB)
	if len(conditions) > 0 {
		query += " WHERE " + strings.Join(conditions, " AND ")
	}

	// Apply ordering - validated against allowlist
	allowedOrders := map[string]bool{"name": true, "dept": true, "role": true, "id": true}
	if orderBy != "" && allowedOrders[orderBy] {
		query += " ORDER BY " + orderBy
	}

	query += " LIMIT 50"

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Role); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthHandler for load balancer checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/employees/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
